MATCH p=(a:Issue)-[:DEPENDS*1..5]->(b:Issue)
WHERE all(n IN nodes(p) WHERE n.resolutionName IS NULL OR n.resolutionName='')
AND size(apoc.coll.toSet(nodes(p)))=size(nodes(p))
AND NOT EXISTS {MATCH (x:Issue)-[:DEPENDS]->(a) WHERE (x.resolutionName IS NULL OR x.resolutionName='') AND NOT x IN nodes(p)}
AND NOT EXISTS {MATCH (b)-[:DEPENDS]->(y:Issue) WHERE (y.resolutionName IS NULL OR y.resolutionName='') AND NOT y IN nodes(p)}
RETURN [n IN nodes(p)|n.issueKey] AS path, [r IN relationships(p)|r.linkId] AS links

